#include <mutex>
int x = 0;
std::mutex mtx;
void func()
{
  for (int i = 0; i < 10000; i++)
  {
    mtx.lock();//加锁，此时其他线程运行到这一行时检测到mtx已经被加锁，这些线程处于阻塞状态，在这一行进行等待
    x += 1;
    mtx.unlock();//解锁，此时被阻塞在mtx.lock()这一行其他线程才可以执行mtx.lock()操作，来继续执行代码。
  }
}
//两个线程执行完后，a的值为20000，说明线程有序访问与操作a

int a = 0;//两个线程均对a进行操作
