}

#include <mutex>
int a = 0;
std::mutex mtx;
void func()
{
  for (int i = 0; i < 10000; i++)
  {
    std::unique_lock<std::mutex> lg(mtx);//指定互斥量类别为mutex,lg是该unique_lock类的变量名,以mtx为参数
