} //两个线程执行完后，a的值为20000，说明线程有序访问与操作a

#include <mutex>
// #include <memory>
int a = 0;
std::timed_mutex mtx;//需要另一种与时间能交互的互斥量
void func()
{
  for (int i = 0; i < 2; i++)
  {
    std::unique_lock<std::timed_mutex> lg(mtx, std::defer_lock);//std::defer_lock是unique_lock中特定的参数，表示对传入的互斥量不自动加锁
    if (lg.try_lock_for(std::chrono::seconds(2)))//尝试在2秒时间内加锁，如果加锁成功则返回true进入下列语句，否则返回false跳出
    {
      std::this_thread::sleep_for(std::chrono::seconds(3));//this_thread：该线程等待3秒
      a++;
    }
  }
}
//最后结果是a等于2，加锁成功后锁定时间大于3，另一线程必定跳过一次加锁与a++，共两次循环

class Log{
private:
    Log(){}
private:
    static Log *Log_instance;//静态指针，初始化为NULL或nullptr
public:
    static Log *GetInstance(){
        if(Log_instance==nullptr){//如果是首次调用获取对象函数，进行对象实例化
            Log_instance = new Log();//把对象存储在内部指针
        }
        return Log_instance;//如果已经创建对象，指针已经指向对象，则直接返回指针
    }
    void func(const string &content){
        cout << content << endl;
    }
};
int main(){
    Log *log = Log::GetInstance();//新创指针指向对象
    log->func("test");
    Log::GetInstance()->func("test");//直接调用对象
}

#include<thread>
#include<mutex>
#include<condition_variable>
std::thread t_detect, t_cap;//t_cap为图像读取的线程，t_detect为图像处理的线程
std::mutex mtx;
std::condition_variable cv_pre_tracked; //初始化
bool Reading = true, consumed = true;

t_cap = std::thread([&]() {   
//更新线程将匿名函数作为该线程的入口，该匿名函数作用为不断读取摄像机或文件的图像并存储
		while (Reading) //摄像机打开，初始化为关闭
		{
		    cap >> cap_frame;
		    cur_frame = cap_frame.clone();//克隆摄像机的图像

				if(consumed)//如果已经被t_detect线程处理，则处理图像后notify_all()来唤醒等待的t_detect
				{
				    std::unique_lock<std::mutex> lock(mtx);//锁定，确保det_image被正确处理
				    det_image = detector.mat_to_image_resize(cur_frame);//detector转化帧为图像，并进行resize
				    consumed = false; //新的图像转化了，还未被处理
				    cv_pre_tracked.notify_all();//通知让cv_pre_tracked休眠的t_detect线程进行处理
				}
		}

		std::unique_lock<std::mutex> lock(mtx);//锁定，确保t_detect读取标记时标记已被更改
		Reading = false;
});

t_detect = std::thread([&]() {
//把以下的匿名函数作为该线程入口
    while (Reading) {//只要未退出，就不断循环
		    auto result = detector.detect_result(*current_image, threshold);//进行处理，具体代码略
		    thread_result_vec.push_back(result);//将处理好的结果存储

		    std::unique_lock<std::mutex> lock(mtx);//锁定，确保det_image被正确访问
		    consumed = true;//处理完毕，更改标记，这样t_cap线程可以修改det_image.
				while (consumed) cv_pre_tracked.wait(lock);
				//如果consumed为true，说明det_image还未更新，则线程在此处被阻塞，进行休眠，等待notify_one或all
		    current_image = det_image;//consumed为false，图像未被处理，可以更新，或者被唤醒后线程往下执行到这一步

    }
});

if (t_cap.joinable()) t_cap.join();
if (t_detect.joinable()) t_detect.join();

std::vector<int> Classifier::classify(const std::vector<cv::Mat> &mats)
{
	std::vector<int> rets; //存储数字识别结果的vector
	std::vector<std::future<int>> futures;//存储future类的vector
	int i = 0;//神经网络中辅助识别的网络结果 nets的索引

	for (const auto &mat : mats)
	{

		network *thisnet = nets[i];
		i++;//每次传入不同的net进行识别，使用不同的 net 对象可以避免多个线程同时访问同一个神经网络模型，从而提高并行处理的效率。

		std::future<int> f = std::async(predictAnImage, thisnet, mat);
		//async 与 thread拥有同样的语法，以predictAnImage函数为线程入口，thisnet和mat作为函数的参数
		//用f来绑定该异步线程，当然f的类型要与predictAnImage函数返回值类型对应
		//异步线程一经创建即立即执行，直到运行完成将结果给传递给f，此时主线程不会等待，将继续运行

		futures.push_back(std::move(f));//std::move相当于线程引用传值，避免进行拷贝而导致资源浪费或处理出错

	}

	for (auto iter = futures.begin(); iter != futures.end(); iter++)//遍历线程返回值
	{

		std::future<int> &f = *iter;//创建引用f指向iter指针对应的元素，避免拷贝浪费资源
		rets.push_back(f.get());//get()获取异步线程结果
	}

	return rets;
}

