inline static std::unordered_set<std::string> FloatParam {
    "AcquisitionFrameRate",  // fps
    "ExposureTime",          // in us, [2000, 10000]
    "Gain",                  // (0, 16]
};

bool Camera::set_params(const std::string &param, const float &value, std::string &what)
{
    if(!check(what))
        return false;

    if(FloatParam.find(param) != FloatParam.end())
    {
        auto ret = MV_CC_SetFloatValue(handle_, param.c_str(), value);
        if(ret != MV_OK)
        {
            what = "Failed to set " + param + " to " + std::to_string(value) + " [" + std::to_string(ret) + "]";
            return false;
        }
    }
    else
    {
        what = "Invalid param: " + param;
        return false;
    }

    return true;
}

