    integralFBz += twoKi * halfez * (1.0f / sampleFreq);
    gx += integralFBx;	// 应用积分反馈项
    gy += integralFBy;
    gz += integralFBz;
}
else {
    integralFBx = 0.0f;	// 防止积分饱和
    integralFBy = 0.0f;
    integralFBz = 0.0f;
}

