// 温度传感器类 - 继承自Sensor
class TemperatureSensor : public Sensor {
private:
    float offset;

public:
    TemperatureSensor(int rate = 1000) : Sensor(rate), offset(0.0f) {
        sensorCount++;
    }

    // 重写虚函数
    float read() override {
        // 模拟读取温度值
        float rawValue = 25.0f + (rand() % 100) * 0.1f;
        return rawValue + offset;
    }

    bool calibrate() override {
        // 温度传感器校准逻辑
        offset = -0.5f; // 模拟校准偏移
        calibrated = true;
        return true;
    }

    // 特有方法
    float readCelsius() { return read(); }
    float readFahrenheit() { return read() * 9.0f / 5.0f + 32.0f; }
};

