/**
 * @brief  使能SysTick中断
 * 将SysTick中断的频率设置为1000Hz
 */
void EnableSystickIT(void)
{
  uint32_t tick_ms = 1; // 1

  HAL_SYSTICK_CLKSourceConfig(SYSTICK_CLKSOURCE_HCLK_DIV8);

  uint32_t reload = SystemCoreClock / 8000 * tick_ms; // SystemCoreClock / 8000 * tick_ms;

  SysTick->CTRL |= SysTick_CTRL_TICKINT_Msk; // Enable SysTick Interrupt
  SysTick->LOAD = reload;
  SysTick->CTRL |= SysTick_CTRL_ENABLE_Msk; // Enable SysTick
}

/**
 * @brief  系统中断1ms
 * 代码的主循环
 */
void SysTick_Handler(void)
{
  HAL_IncTick();
  system_time += 1; // 每次中断增加1ms
  if (is_init)
  {
    storageController->Run(); // 运行存储控制器
    DJImotorHandler->sendControlData();
    DJImotorHandler->AllMotorAliveCheck();
    DJImotorHandler->AllMotorBlockedCheck();

    if (system_time % 100 == 0) // 10hz
    {
      USB_Transmit(storageController->feedback_message_union.data, 6); // 发送反馈消息到USB
    }
  }
}

