void CAN_Transmit(enum CAN_Instance can, uint32_t Id, uint8_t *msg, uint16_t len)
{
    MCAN_Type *ptr = HPM_MCAN0;
    switch (can)
    {
    case CAN0:
        break;
    case CAN1:
        ptr = HPM_MCAN1;
        break;
    case CAN2:
        ptr = HPM_MCAN2;
        break;
    case CAN3:
        ptr = HPM_MCAN3;
        break;
    }

    if (mcan_is_txfifo_full(ptr)) // 如果发送缓冲区满了，直接返回，考虑之后采用清空最老的数据的方法，或者覆盖掉相同ID的数据
    {
        return;
    }
    mcan_tx_frame_t tx_buf;             // 发送缓冲区
    memset(&tx_buf, 0, sizeof(tx_buf)); // 清空缓冲区

    uint32_t put_index = mcan_get_txfifo_put_index(ptr); // 获取发送缓冲区的索引
    // uint32_t put_index = 0;
    tx_buf.std_id = Id; // 设置ID
    tx_buf.dlc = len;

    memcpy(tx_buf.data_8, msg, len);

    mcan_transmit_via_txfifo_nonblocking(ptr, &tx_buf, &put_index);
}

hpm_stat_t mcan_read_rxfifo_mutiframe(MCAN_Type *ptr, uint32_t fifo_index, mcan_rx_message_t *rx_frame,uint8_t frame_num,uint8_t* received_num)
{
    hpm_stat_t status = status_invalid_argument;

    do {
        if ((ptr == NULL) || (rx_frame == NULL)) {
            break;
        }

        uint32_t base_addr;
        uint32_t elem_index;
        uint32_t elem_size;
        uint32_t elem_size_option;
        if (fifo_index == 0) {
            uint32_t rxf0s = ptr->RXF0S;
            if (MCAN_RXF0S_F0FL_GET(rxf0s) == 0) {
                status = status_mcan_rxfifo_empty;
                break;
            }
            base_addr = mcan_get_rxfifo0_base(ptr);
            elem_size_option = MCAN_RXESC_F0DS_GET(ptr->RXESC);
            elem_index = MCAN_RXF0S_F0GI_GET(rxf0s);
        } else {
            uint32_t rxf1s = ptr->RXF1S;
            if (MCAN_RXF1S_F1FL_GET(rxf1s) == 0) {
                status = status_mcan_rxfifo_empty;
                break;
            }
            base_addr = mcan_get_rxfifo1_base(ptr);
            elem_size_option = MCAN_RXESC_F1DS_GET(ptr->RXESC);
            elem_index = MCAN_RXF1S_F1GI_GET(rxf1s);
        }

        if (elem_size_option < 5U) {
            elem_size = 8U + 4U * elem_size_option;
        } else {
            elem_size = 32U + (elem_size_option - 5U) * 16U;
        }
        elem_size += MCAN_MESSAGE_HEADER_SIZE_IN_BYTES;

        uint32_t elem_addr = base_addr + elem_size * elem_index;
        uint32_t *msg_hdr = (uint32_t *) elem_addr;
        uint32_t *msg_data = msg_hdr + 2;
        uint32_t *rx_frame_u32 = (uint32_t *) (&rx_frame[*received_num]);
        rx_frame_u32[0] = msg_hdr[0];
        rx_frame_u32[1] = msg_hdr[1];
        uint8_t msg_size_words = (mcan_get_message_size_from_dlc(rx_frame[(*received_num)].dlc) + 3) / 4;
        for (uint32_t i = 0; i < msg_size_words; i++) {
            rx_frame[(*received_num)].data_32[i] = msg_data[i];
        }

        if (fifo_index == 0) {
            ptr->RXF0A = elem_index;
        } else {
            ptr->RXF1A = elem_index;
        }

        (*received_num)++;

        status = status_success;

    } while (*(received_num)<frame_num);

    return status;
}

