void CAN_Manager::UpdateFeedback()
{
    memset(receive_num, 0, sizeof(receive_num)); // 清空接收数据个数
    mcan_read_rxfifo_mutiframe(HPM_MCAN0, 0, can0_rx0_buff, 8, &receive_num[0][0]); // 读取CAN0的RX FIFO0缓冲区
    mcan_read_rxfifo_mutiframe(HPM_MCAN0, 1, can0_rx1_buff, 8, &receive_num[0][1]); // 读取CAN0的RX FIFO1缓冲区

    mcan_read_rxfifo_mutiframe(HPM_MCAN1, 0, can1_rx0_buff, 8, &receive_num[1][0]); // 读取CAN1的RX FIFO0缓冲区
    mcan_read_rxfifo_mutiframe(HPM_MCAN1, 1, can1_rx1_buff, 8, &receive_num[1][1]); // 读取CAN1的RX FIFO1缓冲区

    mcan_read_rxfifo_mutiframe(HPM_MCAN2, 0, can2_rx0_buff, 8, &receive_num[2][0]); // 读取CAN2的RX FIFO0缓冲区
    mcan_read_rxfifo_mutiframe(HPM_MCAN2, 1, can2_rx1_buff, 8, &receive_num[2][1]); // 读取CAN2的RX FIFO1缓冲区

    mcan_read_rxfifo_mutiframe(HPM_MCAN3, 0, can3_rx0_buff, 8, &receive_num[3][0]); // 读取CAN3的RX FIFO0缓冲区
    mcan_read_rxfifo_mutiframe(HPM_MCAN3, 1, can3_rx1_buff, 8, &receive_num[3][1]); // 读取CAN3的RX FIFO1缓冲区
};

hpm_stat_t uart_rx_trigger_dma(DMA_Type *dma_ptr,
                               uint8_t ch_num,
                               UART_Type *uart_ptr,
                               uint32_t dst,
                               uint32_t size)
{
    dma_handshake_config_t config;

    dma_default_handshake_config(dma_ptr, &config);
    config.ch_index = ch_num;
    config.dst = dst;
    config.dst_fixed = false;
    config.src = (uint32_t)&uart_ptr->RBR;
    config.src_fixed = true;
    config.data_width = DMA_TRANSFER_WIDTH_BYTE;
    config.size_in_byte = size;

    return dma_setup_handshake(dma_ptr, &config, true);
}

hpm_stat_t uart_tx_trigger_dma(DMA_Type *dma_ptr,
                               uint8_t ch_num,
                               UART_Type *uart_ptr,
                               uint32_t src,
                               uint32_t size)
{
    dma_handshake_config_t config;

    dma_default_handshake_config(dma_ptr, &config);
    config.ch_index = ch_num;
    config.dst = (uint32_t)&uart_ptr->THR;
    config.dst_fixed = true;
    config.src = src;
    config.src_fixed = false;
    config.data_width = DMA_TRANSFER_WIDTH_BYTE;
    config.size_in_byte = size;

    return dma_setup_handshake(dma_ptr, &config, true);
}

