/**
 * @brief 初始化裁判系统的串口
 * 串口0用于图传链路
 * 串口7用于常规链路
 */
void bsp_referee_uart_init(void)
{
    convention_uart_dma_done = false;
    convention_received_data_count = 0;

    hpm_stat_t stat;
    /*-------------------------------------常规链路-------------------------------------*/
    // 串口7硬件引脚配置
    HPM_IOC->PAD[IOC_PAD_PA30].FUNC_CTL = IOC_PA30_FUNC_CTL_UART7_RXD;
    HPM_IOC->PAD[IOC_PAD_PA31].FUNC_CTL = IOC_PA31_FUNC_CTL_UART7_TXD;

    // 设置时钟源
    clock_set_source_divider(clock_uart7, clk_src_pll0_clk2, 8);
    clock_add_to_group(clock_uart7, 0);

    uart_config_t uart7_config;
    uart_default_config(HPM_UART7, &uart7_config); 

    // 设置波特率
    uart7_config.baudrate = 115200;
    uart7_config.num_of_stop_bits = stop_bits_1;
    uart7_config.word_length = word_length_8_bits;
    uart7_config.parity = parity_none;
    uart7_config.fifo_enable = true;
    uart7_config.dma_enable = true; // 打开DMA
    uart7_config.src_freq_in_hz = clock_get_frequency(clock_uart7);
    // 设置fifo触发值
    uart7_config.tx_fifo_level = uart_tx_fifo_trg_not_full; 
    uart7_config.rx_fifo_level = uart_fifo_1_byte;
    // 打开空闲中断
    uart7_config.rxidle_config.detect_enable = true;
    uart7_config.rxidle_config.detect_irq_enable = true;
    uart7_config.rxidle_config.idle_cond = uart_rxline_idle_cond_rxline_logic_one;
    uart7_config.rxidle_config.threshold = 20U; // 这里可以设置空闲中断触发的等待时间

    intc_m_enable_irq_with_priority(IRQn_UART7, 1); // 使能串口7中断

    stat = uart_init(HPM_UART7, &uart7_config);

    if (stat != status_success)
    {
        printf("failed to initialize uart7\n");
        while (1)
        {
        // 这里可以做一些异常处理
        }
    }

    // 串口7 DMA接收配置，使用DMA通道1，不同芯片的通道数和DMA数量可能不同
    dma_handshake_config_t uart7_rx_dma_config;
    dmamux_config(HPM_DMAMUX, 1, HPM_DMA_SRC_UART7_RX, true);
    dma_disable_channel(HPM_HDMA, 1);
    dma_default_handshake_config(HPM_HDMA, &uart7_rx_dma_config);
    uart7_rx_dma_config.ch_index = 1; // 设置通道1
    // 设置内存地址
    uart7_rx_dma_config.dst = core_local_mem_to_sys_address(HPM_CORE0, (uint32_t)convention_buff);
