void UART_Transmit(enum UART_Instance uart, uint8_t *data, uint8_t size, enum UART_WORK_MODE work_mode)
{
    UART_Type *ptr = HPM_UART0;
    uint8_t *buff = NULL;
    uint8_t CHN = 0;
    switch (uart)
    {
    case UART0:
        break;
    case UART7:
    {
        ptr = HPM_UART7;
        buff = uart7_buff;
        CHN = UART7_TX_DMA_CHN;
        break;
    }
    default:
        break;
    }
    if (ptr == NULL || buff == NULL)
    {
        return;
    }
    memcpy(buff, data, size);
    switch (work_mode)
    {
    case UART_BLOCK_MODE:
        uart_send_data(ptr, data, size);
        break;
    case UART_DMA_MODE:
        uart_tx_trigger_dma(HPM_HDMA,
                            CHN,
                            ptr,
                            core_local_mem_to_sys_address(BOARD_RUNNING_CORE, (uint32_t)buff),
                            size);
        break;
    }
}

