class AsyncSerial : public std::enable_shared_from_this<AsyncSerial> {
public:
  using Bytes = std::vector<std::uint8_t>;
  using ReadCallback = std::function<void(const Bytes&)>;

  AsyncSerial(std::string device, unsigned int baud_rate)
      : device_(std::move(device)),
        baud_rate_(baud_rate),
        port_(io_),
        work_(boost::asio::make_work_guard(io_)) {}

  ~AsyncSerial() {
    close();
    work_.reset();
    io_.stop();
    if (worker_.joinable()) {
      worker_.join();
    }
  }

  void set_read_callback(ReadCallback cb) {
    on_read_ = std::move(cb);
  }

  bool open() {
    boost::system::error_code ec;
    port_.open(device_, ec);
    if (ec) {
      healthy_.store(false);
      std::cerr << "open failed: " << ec.message() << '\n';
      return false;
    }

    port_.set_option(boost::asio::serial_port_base::baud_rate(baud_rate_));
    port_.set_option(boost::asio::serial_port_base::character_size(8));
    port_.set_option(boost::asio::serial_port_base::parity(
        boost::asio::serial_port_base::parity::none));
    port_.set_option(boost::asio::serial_port_base::stop_bits(
        boost::asio::serial_port_base::stop_bits::one));
    port_.set_option(boost::asio::serial_port_base::flow_control(
        boost::asio::serial_port_base::flow_control::none));

    healthy_.store(true);
    if (!worker_.joinable()) {
      worker_ = std::thread([this] { io_.run(); });
    }
    return true;
  }

  void start_read() {
    boost::asio::post(io_, [self = shared_from_this()] {
      self->read_once();
    });
  }

  void async_write(Bytes bytes) {
    boost::asio::post(io_, [self = shared_from_this(), bytes = std::move(bytes)]() mutable {
      const bool idle = self->write_queue_.empty();
      self->write_queue_.push_back(std::move(bytes));
      if (idle) {
        self->write_next();
      }
    });
  }

  void close() {
    boost::system::error_code ec;
    if (port_.is_open()) {
      port_.cancel(ec);
      port_.close(ec);
    }
    healthy_.store(false);
  }

  bool healthy() const {
    return healthy_.load();
  }

private:
  void read_once() {
    if (!port_.is_open()) {
      healthy_.store(false);
      return;
    }

    port_.async_read_some(
        boost::asio::buffer(read_buffer_),
        [self = shared_from_this()](const boost::system::error_code& ec, std::size_t n) {
          if (ec) {
            if (ec != boost::asio::error::operation_aborted) {
              self->healthy_.store(false);
            }
            return;
          }

          Bytes chunk(self->read_buffer_.begin(), self->read_buffer_.begin() + n);
          if (self->on_read_) {
            self->on_read_(chunk);
          }
          self->read_once();
        });
  }

  void write_next() {
    if (write_queue_.empty() || !port_.is_open()) {
      return;
    }

    boost::asio::async_write(
        port_,
        boost::asio::buffer(write_queue_.front()),
        [self = shared_from_this()](const boost::system::error_code& ec, std::size_t) {
          if (ec) {
            self->healthy_.store(false);
            self->write_queue_.clear();
            return;
          }

          self->write_queue_.pop_front();
          self->write_next();
        });
  }

  std::string device_;
  unsigned int baud_rate_;
  boost::asio::io_context io_;
  boost::asio::serial_port port_;
  boost::asio::executor_work_guard<boost::asio::io_context::executor_type> work_;
  std::thread worker_;
  std::array<std::uint8_t, 512> read_buffer_{};
  std::deque<Bytes> write_queue_;
  ReadCallback on_read_;
  std::atomic_bool healthy_{false};
};

