#include <algorithm>
#include <cstdint>
#include <utility>
#include <vector>

struct Packet {
  std::vector<std::uint8_t> payload;
};

std::uint8_t checksum(const std::vector<std::uint8_t>& data,
                      std::size_t begin,
                      std::size_t end) {
  std::uint8_t sum = 0;
  for (std::size_t i = begin; i < end; ++i) {
    sum = static_cast<std::uint8_t>(sum + data[i]);
  }
  return sum;
}

std::vector<Packet> parse_packets(std::vector<std::uint8_t>& pending) {
  constexpr std::uint8_t kSof = 0xA5;
  constexpr std::size_t kHeaderSize = 2;  // sof + len
  constexpr std::size_t kChecksumSize = 1;
  constexpr std::size_t kMaxPayload = 128;

  std::vector<Packet> packets;

  while (true) {
    auto sof = std::find(pending.begin(), pending.end(), kSof);
    if (sof == pending.end()) {
      pending.clear();
      return packets;
    }
    pending.erase(pending.begin(), sof);

    if (pending.size() < kHeaderSize) {
      return packets;
    }

    const std::size_t payload_len = pending[1];
    if (payload_len > kMaxPayload) {
      pending.erase(pending.begin());
      continue;
    }

    const std::size_t frame_len = kHeaderSize + payload_len + kChecksumSize;
    if (pending.size() < frame_len) {
      return packets;
    }

    const std::uint8_t expected = pending[frame_len - 1];
    const std::uint8_t actual = checksum(pending, 0, frame_len - 1);
    if (actual != expected) {
      pending.erase(pending.begin());
      continue;
    }

    Packet packet;
    packet.payload.assign(pending.begin() + kHeaderSize,
                          pending.begin() + kHeaderSize + payload_len);
    packets.push_back(std::move(packet));
    pending.erase(pending.begin(), pending.begin() + frame_len);
  }
}

void monitor_link(std::shared_ptr<AsyncSerial> serial) {
  using namespace std::chrono_literals;
  int failed_times = 0;

  while (true) {
    std::this_thread::sleep_for(1s);

    if (serial->healthy()) {
      failed_times = 0;
      continue;
    }

    if (++failed_times < 3) {
      continue;
    }

    serial->close();
    std::this_thread::sleep_for(200ms);
    if (serial->open()) {
      serial->start_read();
      failed_times = 0;
    }
  }
}

