int open_serial_port(const char* device, speed_t speed) {
  int fd = ::open(device, O_RDWR | O_NOCTTY);
  if (fd < 0) {
    throw std::runtime_error(std::string("open failed: ") + std::strerror(errno));
  }

  termios tty{};
  if (::tcgetattr(fd, &tty) != 0) {
    ::close(fd);
    throw std::runtime_error(std::string("tcgetattr failed: ") + std::strerror(errno));
  }

  ::cfmakeraw(&tty);
  ::cfsetispeed(&tty, speed);
  ::cfsetospeed(&tty, speed);

  tty.c_cflag |= (CLOCAL | CREAD);
  tty.c_cflag &= ~CSIZE;
  tty.c_cflag |= CS8;
  tty.c_cflag &= ~PARENB;
  tty.c_cflag &= ~CSTOPB;
  tty.c_cflag &= ~CRTSCTS;
  tty.c_iflag &= ~(IXON | IXOFF | IXANY);

  tty.c_cc[VMIN] = 0;
  tty.c_cc[VTIME] = 10;  // 1.0 s timeout

  if (::tcsetattr(fd, TCSANOW, &tty) != 0) {
    ::close(fd);
    throw std::runtime_error(std::string("tcsetattr failed: ") + std::strerror(errno));
  }

  return fd;
}

void write_all(int fd, const std::vector<std::uint8_t>& data) {
  const std::uint8_t* ptr = data.data();
  std::size_t left = data.size();

  while (left > 0) {
    ssize_t n = ::write(fd, ptr, left);
    if (n > 0) {
      ptr += n;
      left -= static_cast<std::size_t>(n);
      continue;
    }
    if (n < 0 && errno == EINTR) {
      continue;
    }
    throw std::runtime_error(std::string("write failed: ") + std::strerror(errno));
  }
}

void read_loop(int fd) {
  std::vector<std::uint8_t> buffer(256);

  while (true) {
    ssize_t n = ::read(fd, buffer.data(), buffer.size());
    if (n > 0) {
      std::vector<std::uint8_t> chunk(buffer.begin(), buffer.begin() + n);
      // chunk 仍然只是字节块，不一定是完整报文。
      continue;
    }
    if (n == 0) {
      continue;  // VTIME 超时，没有读到新数据。
    }
    if (errno == EINTR) {
      continue;
    }
    if (errno == EAGAIN || errno == EWOULDBLOCK) {
      continue;
    }
    throw std::runtime_error(std::string("read failed: ") + std::strerror(errno));
  }
}

int main() {
  int fd = open_serial_port("/dev/ttyUSB0", B115200);
  write_all(fd, {0xA5, 0x01, 0x02, 0xA8});
  read_loop(fd);
  ::close(fd);
}

