struct SpeedCommand
{
    double velocity = 0.0;
    rclcpp::Time stamp;
    bool valid = false;
};

rclcpp::Subscription<std_msgs::msg::Float32>::SharedPtr command_subscriber_;
realtime_tools::RealtimeBuffer<SpeedCommand> command_buffer_;

double integral_error_ = 0.0;
double previous_error_ = 0.0;
bool has_previous_error_ = false;

params_ = param_listener_->get_params();

command_buffer_.initRT(initial_command);
command_subscriber_ = get_node()->create_subscription<std_msgs::msg::Float32>(
    params_.command_topic, 1,
    std::bind(&SimplePidSpeedController::command_callback, this, std::placeholders::_1));

void SimplePidSpeedController::command_callback(const std_msgs::msg::Float32::SharedPtr msg)
{
    SpeedCommand command;
    command.velocity = msg->data;
    command.stamp = get_node()->now();
    command.valid = true;
    command_buffer_.writeFromNonRT(command);
}

reset_controller_state();
clear_command();
command_interfaces_[kCommandEffortIndex].set_value(0.0);

current_velocity = state_interfaces_[kStateVelocityIndex].get_optional().value();
command = command_buffer_.readFromRT();
target_velocity = command_fresh ? command->velocity : 0.0;
error = target_velocity - current_velocity;
effort_command = kp * error + ki * integral_error + kd * derivative_error;
command_interfaces_[kCommandEffortIndex].set_value(effort_command);

if(!params_.debug_mode) {
    return;
}

effort_command_publisher_->try_publish(msg);

