void ChainablePidSpeedController::command_callback(
    const std_msgs::msg::Float32::SharedPtr msg)
{
    if(!accept_external_commands_.load()) {
        return;
    }

    SpeedCommand command;
    command.velocity = msg->data;
    command.stamp = get_node()->now();
    command.valid = true;
    command_buffer_.writeFromNonRT(command);
}

controller_interface::return_type
ChainablePidSpeedController::update_reference_from_subscribers(
    const rclcpp::Time & time,
    const rclcpp::Duration &)
{
    const auto * command = command_buffer_.readFromRT();
    target_velocity = command_fresh ? command->velocity : 0.0;
    reference_interfaces_[0] = target_velocity;
    state_interfaces_values_[0] = target_velocity;
    return controller_interface::return_type::OK;
}

bool ChainablePidSpeedController::on_set_chained_mode(bool chained_mode)
{
    accept_external_commands_.store(!chained_mode);
    reset_controller_state();
    clear_external_command();
    reset_reference(0.0);
    command_interfaces_[0].set_value(0.0);
    return true;
}

void ChainablePidSpeedController::publish_debug(
    double target_velocity,
    double current_velocity,
    double error,
    double effort_command)
{
    if(!params_.debug_mode) {
        return;
    }

    try_publish(target_velocity_publisher_, target_velocity);
    try_publish(current_velocity_publisher_, current_velocity);
    try_publish(error_publisher_, error);
    try_publish(effort_command_publisher_, effort_command);
}

std::vector<hardware_interface::CommandInterface>
ChainablePidSpeedController::on_export_reference_interfaces()
{
    ensure_reference_storage();
    return {hardware_interface::CommandInterface(
        exported_interface_prefix(),
        "velocity",
        &reference_interfaces_[0])};
}

std::vector<hardware_interface::StateInterface>
ChainablePidSpeedController::on_export_state_interfaces()
{
    ensure_reference_storage();
    return {hardware_interface::StateInterface(
        exported_interface_prefix(),
        "target_velocity",
        &state_interfaces_values_[0])};
}

const double current_velocity = state_interfaces_[0].get_optional().value();
const double target_velocity = reference_interfaces_[0];
double error = target_velocity - current_velocity;
integral_error_ += error * period.seconds();
double derivative_error = (error - previous_error_) / period.seconds();
double effort_command = kp * error + ki * integral_error_ + kd * derivative_error;
command_interfaces_[0].set_value(effort_command);

